package reports

import (
	"bytes"
	"database/sql"
	"errors"
	"os"
	"testing"
)

// A replace whose commit failed and whose put-back failed too leaves the row
// describing v1 while v1 is only in tmp/<id>.old (upload.go logs "the next start
// recovers it"). A later replace in the same run must not overwrite that file:
// it is the only copy of the bytes the row still describes.
func TestReplaceDoesNotOverwriteAnUnresolvedSetAside(t *testing.T) {
	r := newRig(t)
	v1, v2, v3 := htmlOf(300, "v1"), htmlOf(400, "v2"), htmlOf(500, "v3")
	rep := r.mustSave(goodForm("steady", "Steady", "published", v1))
	must(t, os.Rename(r.lib.path(rep.ID), r.lib.setAsidePath(rep.ID)))
	must(t, os.WriteFile(r.lib.path(rep.ID), v2, 0o600))

	r.lib.commit = func(tx *sql.Tx) error { tx.Rollback(); return errors.New("injected commit failure") }
	_, _ = r.save(goodForm("steady", "Steady", "published", v3))
	r.lib.commit = func(tx *sql.Tx) error { return tx.Commit() }

	cur, _ := os.ReadFile(r.lib.path(rep.ID))
	old, _ := os.ReadFile(r.lib.setAsidePath(rep.ID))
	if !bytes.Equal(cur, v1) && !bytes.Equal(old, v1) {
		t.Fatal("a replace overwrote tmp/<id>.old while it still held the only copy of the bytes the row describes")
	}
}
